(()=>{const go=e=>{const el=e.target?.closest?.('button,a,[role="button"]');if(!el||!/adquirir\s+un\s+plan/i.test(el.textContent||''))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();try{sessionStorage.setItem('rc_payment_return_pending',JSON.stringify({hash:location.hash,at:Date.now()}))}catch{}location.href='/assets/planes.html?v=20260930-security-preview-1#dj-plans'};['pointerdown','mousedown','touchstart','click'].forEach(n=>document.addEventListener(n,go,true));const patchLabel=()=>document.querySelectorAll('button').forEach(button=>{const w=document.createTreeWalker(button,NodeFilter.SHOW_TEXT),nodes=[];let n;while(n=w.nextNode())nodes.push(n);nodes.forEach(t=>{if(t.nodeValue.includes('Backup actualizado en Drive'))t.nodeValue=t.nodeValue.replace('Backup actualizado en Drive','Actualización y Utilidades Dj.')})});patchLabel();new MutationObserver(patchLabel).observe(document.documentElement,{childList:true,subtree:true})})();